    key:'책은 <em>오프셋을 적으면</em> 덧셈이 없다고 덧붙인다. REDUNDANT 가 끝 오프셋을, COMPACT 이후는 길이를 적고 덧셈은 rec_get_offsets 가 맡는다.',
