    key:'REDUNDANT 레코드는 <em>스스로 오프셋 몇 개를 몇 바이트로</em> 읽을지 안다. 데이터가 127 B 를 넘거나 off-page 칸이 있으면 오프셋이 2 B 로 커진다.',
