    key:'MASK 는 <em>~(~0U << WIDTH) << POS</em> 한 식이다. 폭이 1 이면 책의 2의 거듭제곱이 나오고, 4 면 ZIP_SSIZE 의 0x1E 같은 덩어리가 나온다.',
