    key:'ZIP_SSIZE 4 는 켜짐 · 꺼짐이 아니라 <em>512 << 4 = 8 KB</em> 를 뜻하는 정수다. PAGE_SSIZE 0 도 "없음" 이 아니라 옛 기본 16 KB 라는 값이다.',
    ref:'storage/innobase/include/fsp0types.h', sym:'FSP_FLAGS_GET_ZIP_SSIZE',
