    note:'cell 은 free space 에 append — 책의 slot 은 한 칸 shift',
    why:'새 셀은 셀 영역 끝에 append 한다. 책의 슬롯은 셀마다 하나라 10 과 20 사이에 끼우고 뒤 둘을 옮긴다. InnoDB 는 next 포인터 둘만 고치고, 슬롯 배열은 한 슬롯이 9 개로 넘쳐 쪼갤 때만 memmove 한다.',
