    key:'InnoDB 의 <em>PAGE_DIR_SLOT_SIZE = 2</em>. 다만 InnoDB 는 슬롯을 레코드마다 두지 않고 <em>4~8개마다 하나</em>만 둔다 — 06 에서 본다.',
    ref:'storage/innobase/include/page0page.h', sym:'PAGE_DIR_SLOT_MAX_N_OWNED',
